export const foetalCirculationQuestions: QuizQuestion[] = [
  { question: "Which foetal shunt directs blood from the pulmonary artery to the descending aorta?", options: ["Foramen ovale", "Ductus venosus", "Ductus arteriosus", "Umbilical vein"], correctIndex: 2, explanation: "The ductus arteriosus connects the pulmonary artery to the descending aorta, diverting ~90% of right ventricular output away from the high-resistance pulmonary vasculature into the systemic circulation. It is kept patent by low PaO₂ and prostaglandins (PGE₂), and closes within 10-15 hours of birth as PaO₂ rises and PGE₂ levels fall." },
  { question: "What maintains patency of the ductus arteriosus in utero?", options: ["High PaO₂ and low prostaglandins", "Low PaO₂ and prostaglandin E₂", "Nitric oxide and endothelin", "Sympathetic stimulation"], correctIndex: 1, explanation: "The ductus arteriosus is kept open by two key factors: the low foetal PaO₂ (3-4 kPa) and circulating prostaglandins (PGE₂ and PGI₂). At birth, rising PaO₂ causes smooth muscle constriction while falling PGE₂ (from placental removal and increased pulmonary metabolism) facilitates closure. This is why indomethacin (a COX inhibitor) can be used to close a patent DA in premature infants." },
  { question: "The P50 of foetal haemoglobin (HbF) is approximately 2.7 kPa compared to 3.5 kPa for adult HbA. What is the primary reason for this difference?", options: ["HbF has more subunits than HbA", "HbF binds 2,3-DPG less avidly, maintaining a left-shifted curve", "HbF is less concentrated in foetal blood", "The Haldane effect is stronger in the foetus"], correctIndex: 1, explanation: "HbF has two gamma (γ) chains instead of beta (β) chains. These γ chains bind 2,3-DPG less avidly than β chains, keeping the ODC left-shifted (higher O₂ affinity, lower P50). This facilitates O₂ uptake from maternal blood at the placenta, where PaO₂ is only ~4 kPa. Despite the low PaO₂, the foetus compensates with high Hb concentration (~180 g/L) and high cardiac output (~450 mL/kg/min)." },
  { question: "What is the primary trigger for functional closure of the foramen ovale at birth?", options: ["Rising PaO₂ causing smooth muscle contraction", "Left atrial pressure exceeding right atrial pressure", "Prostaglandin withdrawal", "Vagal stimulation during first breath"], correctIndex: 1, explanation: "The foramen ovale is a flap valve. In utero, RA pressure exceeds LA pressure, keeping it open. At birth, the first breath dramatically reduces PVR, increasing pulmonary blood flow and LA filling. Simultaneously, cord clamping removes the low-resistance placental circuit, increasing SVR. The resulting rise in LA pressure above RA pressure pushes the septum primum against the septum secundum, functionally closing the foramen ovale." },
  { question: "A neonate has SpO₂ 95% on the right hand but 82% on the foot. What does this pre-post ductal gradient suggest?", options: ["Coarctation of the aorta with no shunting", "Right-to-left shunting through a patent ductus arteriosus", "Left-to-right shunting through a VSD", "Normal transitional circulation"], correctIndex: 1, explanation: "The right hand (pre-ductal) is supplied by the ascending aorta proximal to the ductus arteriosus, while the foot (post-ductal) receives blood distal to the DA. A >5% SpO₂ difference indicates right-to-left shunting through a patent DA — deoxygenated blood from the PA mixing with aortic blood. This pattern is seen in persistent pulmonary hypertension of the newborn (PPHN) and suggests high PVR preventing the normal transition to series circulation." },
];

