export const starlingForcesQuestions: QuizQuestion[] = [
  { question: "In the revised Starling model, what is the primary barrier to protein filtration across the capillary?", options: ["Endothelial cell junctions", "Basement membrane", "Endothelial glycocalyx", "Pericytes"], correctIndex: 2, explanation: "The revised Starling-Levick model (2010) identifies the endothelial glycocalyx as the primary semi-permeable barrier. This 0.5-3 µm gel-like layer of proteoglycans and glycosaminoglycans acts as a molecular sieve, excluding plasma proteins and creating a protein-free sub-glycocalyx space. This means the effective oncotic gradient is πc − πsg (sub-glycocalyx), not πc − πi." },
  { question: "According to the revised Starling model, how does filtered fluid return to the circulation?", options: ["Reabsorption at the venular end of capillaries", "Exclusively via lymphatic drainage", "Pinocytosis by endothelial cells", "Active transport across endothelial cells"], correctIndex: 1, explanation: "The classic model predicted reabsorption at the venular end where Pc drops below πc. The revised model shows that filtration occurs along the entire capillary length because the effective oncotic gradient (πc − πsg) is much smaller than (πc − πi). Fluid return to the circulation depends entirely on lymphatic drainage, which can increase 10-50× before being overwhelmed." },
  { question: "Which of the following best explains why crystalloid boluses are poorly retained intravascularly in sepsis?", options: ["Reduced cardiac output", "Glycocalyx damage increasing capillary permeability", "Increased renal excretion", "Reduced oncotic pressure from dilution"], correctIndex: 1, explanation: "Sepsis causes glycocalyx shedding (measurable by syndecan-1 levels), dramatically increasing capillary permeability. With a damaged glycocalyx, the sub-glycocalyx space fills with protein → πsg rises → the effective oncotic gradient (πc − πsg) falls → filtration increases → crystalloid rapidly moves into the interstitium. This is why fluid resuscitation in sepsis causes significant oedema." },
  { question: "Atrial natriuretic peptide (ANP) released during fluid overload worsens oedema by:", options: ["Increasing renal sodium retention", "Directly damaging the endothelial glycocalyx", "Constricting lymphatic vessels", "Reducing plasma oncotic pressure"], correctIndex: 1, explanation: "ANP is released from atrial myocytes in response to volume expansion. Beyond its natriuretic effect, ANP directly causes glycocalyx shedding, increasing capillary permeability. This creates a vicious cycle: fluid overload → ANP → glycocalyx damage → increased filtration → more oedema. This is a key reason why excessive fluid administration is self-perpetuating and harmful." },
  { question: "Context-sensitive volume kinetics explains that crystalloid remains intravascular longer during:", options: ["Normovolaemia", "Hypervolaemia", "Hypovolaemia", "It is the same regardless of volume status"], correctIndex: 2, explanation: "In hypovolaemia, capillary hydrostatic pressure (Pc) is reduced, decreasing the filtration gradient. Crystalloid therefore remains intravascular longer. In normovolaemia/hypervolaemia, higher Pc drives faster filtration into the interstitium. This concept (Hahn, 2010) parallels context-sensitive half-time in pharmacology and has important implications for perioperative fluid management — fluid given to a depleted patient is more effective than the same volume given to a normovolaemic patient." },
];

