export const bronchospasticFailureQuestions: QuizQuestion[] = [
  { question: "A ventilated asthmatic patient suddenly becomes hypotensive with rising airway pressures. What is the most likely cause and immediate action?", options: ["Pneumothorax — insert chest drain", "Dynamic hyperinflation — disconnect from ventilator and allow prolonged expiration", "Anaphylaxis — give adrenaline", "ETT obstruction — pass suction catheter"], correctIndex: 1, explanation: "Dynamic hyperinflation (gas trapping) causes auto-PEEP → reduced venous return → cardiovascular collapse. The immediate action is to disconnect from the ventilator and allow passive expiration. Bilateral tension pneumothorax should also be excluded (thoracostomies). This is the most common cause of PEA arrest in ventilated asthmatics." },
  { question: "In life-threatening asthma, which finding on ABG is most concerning?", options: ["PaO₂ 9 kPa on air", "PaCO₂ 3.5 kPa", "Normal PaCO₂ (5 kPa)", "pH 7.48"], correctIndex: 2, explanation: "A normal PaCO₂ in acute asthma is sinister — it indicates the patient is tiring and can no longer hyperventilate to compensate. In acute asthma, PaCO₂ should be LOW (due to tachypnoea). A rising or normal PaCO₂ suggests impending respiratory arrest and should prompt consideration of intubation." },
  { question: "Which is the ideal induction agent for intubation of a patient with severe bronchospasm?", options: ["Thiopentone", "Ketamine", "Midazolam", "Etomidate"], correctIndex: 1, explanation: "Ketamine is a direct bronchodilator (smooth muscle relaxation) with sympathomimetic properties that maintain haemodynamic stability. Propofol also has bronchodilatory properties and is an acceptable alternative. Thiopentone should be avoided as it can cause histamine release and worsen bronchospasm." },
  { question: "What is the primary mechanism of action of the Sedaconda (AnaConDa) device?", options: ["It nebulises liquid volatile agent into fine particles", "It uses an activated carbon reflector to recapture and re-deliver exhaled volatile agent", "It converts IV anaesthetic agents into inhaled form", "It is a specialised nebuliser for bronchodilator delivery"], correctIndex: 1, explanation: "The Sedaconda/AnaConDa device contains an activated carbon fibre reflector that adsorbs ~90% of exhaled volatile agent and releases it back to the patient on the next inspiration. Liquid volatile is infused via syringe pump, evaporates within the device, and is delivered without needing an anaesthetic machine." },
  { question: "Which ventilator setting is MOST important to adjust in a ventilated patient with severe bronchospasm?", options: ["Increase PEEP to 15 cmH₂O to splint airways open", "Increase respiratory rate to 20/min to blow off CO₂", "Decrease respiratory rate and prolong expiratory time (I:E 1:4–1:5)", "Increase tidal volume to 12 ml/kg to improve ventilation"], correctIndex: 2, explanation: "The priority is to allow adequate expiratory time to prevent gas trapping. This means a LOW respiratory rate (8–12/min), prolonged I:E ratio (1:3 to 1:5), and high inspiratory flow rate. Permissive hypercapnia is accepted. Increasing PEEP or RR will worsen dynamic hyperinflation." },
  { question: "NIV is first-line treatment for acute respiratory failure in which condition?", options: ["Life-threatening asthma", "Acute hypercapnic exacerbation of COPD (pH 7.25–7.35)", "Acute pulmonary oedema with hypotension", "Pneumothorax"], correctIndex: 1, explanation: "NIV (BiPAP) is first-line for acute hypercapnic respiratory failure in COPD with pH 7.25–7.35. Strong Cochrane evidence shows it reduces intubation rates, mortality, and length of stay. NIV is NOT first-line in acute asthma (BTS/SIGN guidelines) and is contraindicated in undrained pneumothorax." },
];

export const prognosticationIcuQuestions: QuizQuestion[] = [
  { question: "A patient has a cardiac arrest and is resuscitated. At what time point should formal neurological prognostication begin (ERC/ESICM 2021)?", options: ["Immediately on ICU admission", "At 24 hours post-ROSC", "At ≥72 hours post-ROSC (or after rewarming)", "At 7 days post-ROSC"], correctIndex: 2, explanation: "ERC/ESICM 2021 guidelines recommend multimodal prognostication at ≥72 h after ROSC (or ≥72 h after completing rewarming if TTM was used). Earlier assessment risks premature conclusions due to residual sedation, hypothermia, and metabolic derangement. At least 2 concordant poor prognostic signs are required." },
  { question: "A family requests that 'everything is done' for their relative with end-stage COPD and metastatic cancer. The ICU team believes ICU admission would be futile. Under UK law, who makes the final decision?", options: ["The family, as next of kin have legal authority to demand treatment", "The patient's GP, as they know the patient best", "The treating clinician(s), after considering the patient's best interests", "The hospital ethics committee must make all such decisions"], correctIndex: 2, explanation: "Under UK law, families cannot demand treatment — they are consulted but do not have authority to insist on treatments clinicians judge to be futile or not in the patient's best interests. The treating clinician makes the decision, considering the patient's values, wishes, and clinical factors. If disagreement persists, mediation, second opinions, and ultimately the Court of Protection can be involved." },
  { question: "Which of the following is TRUE regarding DNACPR decisions?", options: ["DNACPR means all active treatment should be stopped", "DNACPR only applies to cardiopulmonary resuscitation — other treatments continue as appropriate", "DNACPR requires written consent from the patient or family", "DNACPR decisions cannot be made without the patient's agreement"], correctIndex: 1, explanation: "DNACPR applies ONLY to CPR in the event of cardiac or respiratory arrest. It does NOT mean withdrawal of other treatments — patients with DNACPR may still be appropriate for ICU admission, intubation, antibiotics, surgery, etc. DNACPR is a clinical decision that does not require patient consent (though discussion is recommended). It is a common and dangerous misconception that DNACPR equates to 'not for active treatment'." },
  { question: "Which domain of Post-Intensive Care Syndrome (PICS) is most strongly predicted by ICU delirium?", options: ["Physical weakness", "Cognitive impairment", "Chronic pain", "Dysphagia"], correctIndex: 1, explanation: "Duration of ICU delirium is the strongest predictor of long-term cognitive impairment after critical illness. Cognitive deficits may include memory impairment, reduced executive function, and impaired processing speed — similar to mild TBI or early Alzheimer's on neuropsychological testing. This may persist for years and is a major barrier to return to work." },
  { question: "A patient with ICU-acquired weakness has areflexia, distal weakness, and nerve conduction studies showing reduced CMAP amplitudes with preserved conduction velocities. What is the most likely diagnosis?", options: ["Guillain-Barré syndrome", "Critical illness polyneuropathy (CIP)", "Critical illness myopathy (CIM)", "Myasthenia gravis"], correctIndex: 1, explanation: "CIP is an axonal sensorimotor polyneuropathy with reduced CMAP and SNAP amplitudes but preserved conduction velocities (differentiating it from demyelinating neuropathies like GBS). CIM shows small-amplitude, short-duration motor unit potentials with relatively preserved reflexes initially. CIP and CIM often coexist (CIPNM). Sepsis and multi-organ failure are the strongest risk factors." },
  { question: "The doctrine of double effect permits which of the following in end-of-life care?", options: ["Administering a lethal dose of opioid with the intention of ending life", "Giving morphine to relieve dyspnoea, accepting that it may hasten death", "Withdrawing ventilation specifically to cause death more quickly", "Withholding antibiotics to hasten death from infection"], correctIndex: 1, explanation: "The doctrine of double effect permits giving medications with the PRIMARY intention of relieving suffering, even if a foreseeable (but unintended) consequence is hastening death. The key distinction is intent — the good effect (comfort) is intended, the bad effect (death) is foreseen but not desired. This is legally and ethically distinct from euthanasia, where the primary intention is to cause death." },
];

export const acutePancreatitisQuestions: QuizQuestion[] = [
  { question: "A 55-year-old presents with epigastric pain, vomiting and a serum lipase of 1800 U/L (ULN 60). According to the revised Atlanta classification, which of the following defines SEVERE acute pancreatitis?", options: ["Glasgow score ≥3 at 48 hours", "Pancreatic necrosis on CT", "Persistent organ failure (>48 hours)", "CRP >150 mg/L at 48 hours"], correctIndex: 2, explanation: "Revised Atlanta 2012 defines severe acute pancreatitis by persistent organ failure (>48h) in any of the respiratory, cardiovascular or renal systems, scored using the modified Marshall score. Glasgow ≥3, CRP >150 and necrosis predict severity but do not by themselves define it. Transient organ failure (<48h) is moderately severe disease." },
  { question: "Which fluid regimen is supported by the WATERFALL trial (2022) for initial resuscitation in acute pancreatitis?", options: ["Aggressive 0.9% saline at 3 mL/kg/h with 20 mL/kg bolus", "Aggressive Hartmann's at 3 mL/kg/h with 20 mL/kg bolus", "Moderate balanced crystalloid (1.5 mL/kg/h, 10 mL/kg bolus only if hypovolaemic)", "Albumin 4.5% titrated to CVP 12–15 mmHg"], correctIndex: 2, explanation: "The WATERFALL trial was stopped early for safety: aggressive fluid resuscitation (20 mL/kg bolus + 3 mL/kg/h) caused significantly more fluid overload (20.5% vs 6.3%) without reducing progression to moderate-to-severe disease. Moderate, goal-directed resuscitation with balanced crystalloid is now standard. Saline causes hyperchloraemic acidosis and worsens SIRS." },
  { question: "When is ERCP indicated in the first 24–72 hours of acute gallstone pancreatitis?", options: ["All patients with gallstone pancreatitis", "Only if ALT >150 IU/L", "Only if there is concurrent cholangitis or persistent biliary obstruction", "Only if pancreatic necrosis is seen on CT"], correctIndex: 2, explanation: "Multiple RCTs and meta-analyses (including the Dutch APEC trial) show no benefit of routine early ERCP in gallstone pancreatitis without cholangitis. ERCP is indicated within 24h for cholangitis and within 72h for persistent biliary obstruction (rising bilirubin, dilated CBD). Cholecystectomy should be performed on the same admission for mild gallstone pancreatitis to prevent recurrence." },
  { question: "A patient with severe pancreatitis has been on the ICU for 9 days with persistent organ failure. Repeat CT shows 40% pancreatic necrosis with gas locules. They are spiking new fevers and CRP has risen. What is the next step?", options: ["Immediate open necrosectomy", "Start meropenem, perform image-guided percutaneous drainage as first step (step-up approach)", "Continue antibiotics alone — surgery contraindicated in early necrosis", "Urgent total pancreatectomy"], correctIndex: 1, explanation: "The PANTER trial (2010) established the step-up approach for infected necrosis: percutaneous (or endoscopic transgastric) drainage first, followed by minimally invasive video-assisted retroperitoneal debridement (VARD) only if needed, with open necrosectomy as last resort. This reduces major complications, new-onset organ failure and long-term morbidity vs primary open necrosectomy. Carbapenem (meropenem) provides best pancreatic penetration." },
  { question: "Which of the following is NOT an indication for tertiary HPB centre referral in acute pancreatitis?", options: ["Mild gallstone pancreatitis with Glasgow 1, awaiting cholecystectomy", "Pancreatic necrosis >30% on CT", "Persistent organ failure beyond 48 hours", "Suspected infected necrosis requiring drainage"], correctIndex: 0, explanation: "Mild gallstone pancreatitis with low severity scores can be managed at the index hospital with same-admission cholecystectomy. Tertiary referral is indicated for predicted/established severe disease, persistent organ failure, significant necrosis, infected collections requiring intervention, vascular complications, abdominal compartment syndrome, and need for advanced endoscopy or HPB surgery not available locally." },
  { question: "Regarding nutrition in severe acute pancreatitis, which statement is TRUE?", options: ["Patients should be NBM until amylase normalises", "TPN is preferred to avoid stimulating the pancreas", "Early enteral nutrition (NG or NJ) within 24–72h reduces infectious complications and mortality", "Nasojejunal feeding is mandatory; nasogastric is contraindicated"], correctIndex: 2, explanation: "Multiple RCTs and meta-analyses (including PYTHON trial) show early enteral nutrition (within 24–72h) reduces infectious complications, organ failure and mortality compared with TPN. NG and NJ feeding are equivalent in tolerability and outcomes — start with NG, advance to NJ only if intolerance. TPN is reserved for those who fail enteral after 5–7 days. Enteral feeding maintains gut barrier function and reduces bacterial translocation." },
  { question: "Prophylactic antibiotics in acute pancreatitis:", options: ["Reduce mortality and should be given to all severe cases", "Should be given to all patients with predicted severe disease", "Reduce infected necrosis rates and are recommended at 72h", "Do not reduce mortality or infected necrosis and are not routinely indicated"], correctIndex: 3, explanation: "Multiple high-quality RCTs and Cochrane reviews show prophylactic antibiotics in acute pancreatitis (including with necrosis) do not reduce mortality, infected necrosis rates, or need for surgery. They drive antimicrobial resistance and fungal superinfection. Antibiotics should only be used for proven extra-pancreatic infection (cholangitis, pneumonia, line sepsis) or proven infected necrosis. Carbapenems have the best pancreatic penetration." },
];
